-- engine: sqlite

CREATE TABLE todo(
	id INTEGER PRIMARY KEY,
	title TEXT NOT NULL,
	done INTEGER NOT NULL DEFAULT 0 CHECK (done IN (0, 1)),
	note TEXT
) STRICT;

CREATE TABLE tag(
	todo_id INTEGER NOT NULL REFERENCES todo(id),
	name TEXT NOT NULL,
	PRIMARY KEY (todo_id, name)
) STRICT, WITHOUT ROWID;
